INSERT INTO tutorials (title, slug, summary, content, category, category_slugs, related_tool_slugs, cover_image, cover_type, difficulty, estimated_minutes, audiences, tags, views, likes, seo_title, seo_description, status) VALUES
('ChatGPT 高效使用指南','chatgpt-guide','ChatGPT 高效使用指南：围绕新手入门的真实任务，演示如何准备素材、输入提示词、迭代结果并完成可交付内容。','{"steps":[{"title":"明确任务目标","body":"先把这次使用 ChatGPT 要完成的结果写清楚，例如生成草稿、整理资料、制作页面或输出行动清单。","tip":"把目标、受众和交付格式写在同一段里。","pitfall":"只输入一个宽泛主题，容易得到空洞结果。"},{"title":"准备真实素材","body":"整理和 新手入门 相关的背景、参考样例、限制条件和已有资料，让 AI 有足够上下文。","tip":"把素材分成背景、要求、示例和禁区四类。","pitfall":"缺少约束会导致输出风格飘忽。"},{"title":"输入结构化提示词","body":"使用角色、任务、材料、输出格式、检查标准五段式提示词，先拿到第一版可修改结果。","tip":"先要结构，再要细节，不要一次要求完美。","pitfall":"让 AI 同时完成太多目标会降低稳定性。"},{"title":"追问并迭代结果","body":"根据第一版结果逐项追问，让 ChatGPT 修改语气、结构、事实、格式和缺失信息。","tip":"每轮只改一类问题，效果更可控。","pitfall":"没有保存有效提示词，下一次难以复用。"},{"title":"人工核对和发布","body":"最终内容需要人工核对事实、价格、引用、版权和敏感信息，再进入正式发布或交付流程。","tip":"建立自己的检查清单。","pitfall":"直接复制 AI 输出用于正式场景风险较高。"}],"promptBlocks":[{"title":"ChatGPT 高效使用指南通用提示词","prompt":"请作为新手入门助手，围绕「[主题]」完成任务。要求：1. 先确认目标和受众；2. 输出清晰步骤；3. 给出可复制内容；4. 标注需要人工核对的信息。"}],"faq":[{"question":"ChatGPT 高效使用指南适合新手吗？","answer":"适合，新手可以按步骤完成一个小任务。"},{"question":"教程里的提示词能直接复制吗？","answer":"可以复制，但要把变量替换成你的真实任务信息。"},{"question":"生成结果能直接交付吗？","answer":"不建议直接交付，至少要核对事实、格式、语气和敏感信息。"}],"commonErrors":[{"title":"任务描述太宽泛","wrong":"只写“帮我做一个方案”。","reason":"AI 无法判断目标、受众和输出格式。","fix":"补充目标、受众、素材、限制和检查标准。"},{"title":"不核对事实就发布","wrong":"直接复制 AI 输出。","reason":"价格、链接、引用和功能可能变化。","fix":"发布前人工核对来源和关键事实。"},{"title":"没有保存可复用模板","wrong":"每次从零开始提问。","reason":"难以稳定复现好结果。","fix":"把有效提示词保存为模板。"}],"optimizationTips":["把好结果沉淀成模板","用真实案例替换空泛描述","让 AI 输出自检清单","重要内容用第二个工具交叉核对"]}'::jsonb,'新手入门',ARRAY['beginner','ai-writing'],ARRAY['chatgpt'],'','gradient','新手',18,ARRAY['AI 新手','学生','职场用户'],ARRAY['新手入门','ChatGPT','新手'],4800,240,'ChatGPT 高效使用指南：步骤、提示词和常见错误','ChatGPT 高效使用指南，包含适合人群、使用工具、详细步骤、可复制提示词和优化建议。','published'),
('DeepSeek 新手入门教程','deepseek-beginner','DeepSeek 新手入门教程：围绕新手入门的真实任务，演示如何准备素材、输入提示词、迭代结果并完成可交付内容。','{"steps":[{"title":"明确任务目标","body":"先把这次使用 DeepSeek 要完成的结果写清楚，例如生成草稿、整理资料、制作页面或输出行动清单。","tip":"把目标、受众和交付格式写在同一段里。","pitfall":"只输入一个宽泛主题，容易得到空洞结果。"},{"title":"准备真实素材","body":"整理和 新手入门 相关的背景、参考样例、限制条件和已有资料，让 AI 有足够上下文。","tip":"把素材分成背景、要求、示例和禁区四类。","pitfall":"缺少约束会导致输出风格飘忽。"},{"title":"输入结构化提示词","body":"使用角色、任务、材料、输出格式、检查标准五段式提示词，先拿到第一版可修改结果。","tip":"先要结构，再要细节，不要一次要求完美。","pitfall":"让 AI 同时完成太多目标会降低稳定性。"},{"title":"追问并迭代结果","body":"根据第一版结果逐项追问，让 DeepSeek 修改语气、结构、事实、格式和缺失信息。","tip":"每轮只改一类问题，效果更可控。","pitfall":"没有保存有效提示词，下一次难以复用。"},{"title":"人工核对和发布","body":"最终内容需要人工核对事实、价格、引用、版权和敏感信息，再进入正式发布或交付流程。","tip":"建立自己的检查清单。","pitfall":"直接复制 AI 输出用于正式场景风险较高。"}],"promptBlocks":[{"title":"DeepSeek 新手入门教程通用提示词","prompt":"请作为新手入门助手，围绕「[主题]」完成任务。要求：1. 先确认目标和受众；2. 输出清晰步骤；3. 给出可复制内容；4. 标注需要人工核对的信息。"}],"faq":[{"question":"DeepSeek 新手入门教程适合新手吗？","answer":"适合，新手可以按步骤完成一个小任务。"},{"question":"教程里的提示词能直接复制吗？","answer":"可以复制，但要把变量替换成你的真实任务信息。"},{"question":"生成结果能直接交付吗？","answer":"不建议直接交付，至少要核对事实、格式、语气和敏感信息。"}],"commonErrors":[{"title":"任务描述太宽泛","wrong":"只写“帮我做一个方案”。","reason":"AI 无法判断目标、受众和输出格式。","fix":"补充目标、受众、素材、限制和检查标准。"},{"title":"不核对事实就发布","wrong":"直接复制 AI 输出。","reason":"价格、链接、引用和功能可能变化。","fix":"发布前人工核对来源和关键事实。"},{"title":"没有保存可复用模板","wrong":"每次从零开始提问。","reason":"难以稳定复现好结果。","fix":"把有效提示词保存为模板。"}],"optimizationTips":["把好结果沉淀成模板","用真实案例替换空泛描述","让 AI 输出自检清单","重要内容用第二个工具交叉核对"]}'::jsonb,'新手入门',ARRAY['beginner','ai-writing','ai-code'],ARRAY['deepseek'],'','gradient','新手',16,ARRAY['学生','办公族','程序员'],ARRAY['新手入门','DeepSeek','新手'],5141,253,'DeepSeek 新手入门教程：步骤、提示词和常见错误','DeepSeek 新手入门教程，包含适合人群、使用工具、详细步骤、可复制提示词和优化建议。','published'),
